    Bug 2015922 - Intermittent comm/calendar/test/browser/browser_eventUndoRedo.js | testMenuBarAddEventUndoRedo - Test timed out. r=arschmitz


    All of these fixes were necessary for it to pass --verify on windows debug.

    For the cases the window doesn't get focus (activated), there may be a bug elsewhere.
    The window(s) simply do not come to the foreground on Windows. But it seems they do not have to for this to work.

    Differential Revision: https://phabricator.services.mozilla.com/D286553

diff --git a/calendar/test/CalendarTestUtils.sys.mjs b/calendar/test/CalendarTestUtils.sys.mjs
index 26abf2ade49..ee83bbb9073 100644
--- a/calendar/test/CalendarTestUtils.sys.mjs
+++ b/calendar/test/CalendarTestUtils.sys.mjs
@@ -1006,7 +1006,7 @@ export const CalendarTestUtils = {
    *
    * @returns {Promise<Window>}
    */
-  waitForEventDialog(mode = "view") {
+  async waitForEventDialog(mode = "view") {
     const uri =
       mode === "edit"
         ? "chrome://calendar/content/calendar-event-dialog.xhtml"
@@ -1016,10 +1016,29 @@ export const CalendarTestUtils = {
       if (win.document.documentURI != uri) {
         return false;
       }
-
-      Assert.report(false, undefined, undefined, "Event dialog opened");
+      Assert.report(
+        false,
+        undefined,
+        undefined,
+        `Event dialog opened; ${Services.focus.activeWindow?.location} active`
+      );
       if (Services.focus.activeWindow != win) {
-        await BrowserTestUtils.waitForEvent(win, "activate");
+        let focusTimeoutId;
+        const focusTimeout = new Promise(resolve => {
+          focusTimeoutId = win.setTimeout(() => {
+            Assert.report(false, undefined, undefined, `Will force focus to ${win.location}`);
+            win.focus();
+            resolve();
+          }, 5000);
+        });
+        await Promise.race([BrowserTestUtils.waitForEvent(win, "activate"), focusTimeout]);
+        win.clearTimeout(focusTimeoutId);
+        Assert.report(
+          false,
+          undefined,
+          undefined,
+          `${Services.focus.activeWindow?.location} now active - ${Services.focus.focusedWindow?.location} has focus`
+        );
       }
       if (mode === "edit") {
         const iframe = win.document.getElementById("calendar-item-panel-iframe");
